(()=>{const root=document.documentElement,body=document.body;root.classList.add('force-native-cursor');const fine=matchMedia('(hover:hover) and (pointer:fine)').matches,reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;if(!fine||reduce){document.querySelectorAll('.cursor,.cursor-dot,.cursor-ring').forEach(x=>x.remove());return}const custom=document.querySelector('.cursor,.cursor-dot,.cursor-ring');if(!custom)return;body.classList.add('custom-cursor-ready');let seen=false;const showNative=()=>{if(seen)return;seen=true;root.classList.add('force-native-cursor')};window.addEventListener('pointermove',showNative,{once:true,passive:true});window.addEventListener('blur',()=>root.classList.add('force-native-cursor'));document.addEventListener('visibilitychange',()=>{if(!document.hidden)root.classList.add('force-native-cursor')});document.querySelectorAll('a,button,input,textarea,select,[role="button"],.lang-control,.cite-this,.ai-answer').forEach(el=>{el.addEventListener('pointerenter',()=>root.classList.add('force-native-cursor'),{passive:true})})})();
